package org.apache.commons.jxpath.ri.compiler;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import javax.xml.namespace.QName;
import org.apache.commons.jxpath.EvalContext;
import org.apache.commons.jxpath.Pointer;
import org.apache.commons.jxpath.ri.EvalContext;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.apache.commons.jxpath.util.ValueUtils;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class Expression_iteratePointers_TriageGen0Test {

    private Expression expression;
    private EvalContext context;
    private EvalContext rootContext;
    private Pointer currentNodePointer;

    @Before
    public void setUp() {
        // Expression is abstract because compute() is abstract
        expression = Mockito.mock(Expression.class, Mockito.CALLS_REAL_METHODS);
        context = mock(EvalContext.class);
        rootContext = mock(EvalContext.class);
        currentNodePointer = mock(Pointer.class);

        when(context.getRootContext()).thenReturn(rootContext);
        when(rootContext.getCurrentNodePointer()).thenReturn(currentNodePointer);
    }

    @Test
    public void testIteratePointers_ResultIsNull() {
        // Case: result == null -> returns Collections.EMPTY_LIST.iterator()
        when(expression.compute(context)).thenReturn(null);

        Iterator<?> iterator = expression.iteratePointers(context);

        assertNotNull(iterator);
        assertFalse("Iterator should be empty when result is null", iterator.hasNext());
    }

    @Test
    public void testIteratePointers_ResultIsEvalContext() {
        // Case: result instanceof EvalContext -> returns (EvalContext) result
        EvalContext mockContextResult = mock(EvalContext.class);
        when(expression.compute(context)).thenReturn(mockContextResult);

        Iterator<?> iterator = expression.iteratePointers(context);

        assertNotNull(iterator);
        assertEquals(mockContextResult, iterator);
    }

    @Test
    public void testIteratePointers_ResultIsList() {
        // Case: result is a standard object (List) -> returns PointerIterator
        // We need to mock the behavior of ValueUtils.iterate(result) 
        // Since ValueUtils is likely a static utility, we provide a List that works with it.
        List<String> list = Arrays.asList("a", "b");
        when(expression.compute(context)).thenReturn(list);
        when(currentNodePointer.getLocale()).thenReturn(java.util.Locale.US);

        Iterator<?> iterator = expression.iteratePointers(context);

        assertNotNull(iterator);
        assertTrue(iterator.hasNext());

        // Note: PointerIterator wraps the values. 
        // Since we cannot easily mock ValueUtils.iterate if it's static, 
        // we rely on the real implementation of ValueUtils if available in the classpath.
        // The test ensures the branch coverage for the final return statement.
    }

    @Test
    public void testIteratePointers_ResultIsSingleObject() {
        // Case: result is a single object (not null, not EvalContext, not a collection)
        // This tests the branch where ValueUtils.iterate wraps a non-collection object.
        String singleValue = "test";
        when(expression.compute(context)).thenReturn(singleValue);
        when(currentNodePointer.getLocale()).thenReturn(java.util.Locale.ENGLISH);

        Iterator<?> iterator = expression.iteratePointers(context);

        assertNotNull(iterator);
        assertTrue(iterator.hasNext());
    }
}
